"use client";

import { cn } from "@workspace/ui/lib/utils";
import type { ReactNode } from "react";
import { type LogsData, LogViewerProvider } from "./log-viewer.context";
import { LogViewerCountChart } from "./log-viewer.count-chart";
import { LogViewerListContent, LogViewerListHeader } from "./log-viewer.list";
import { LogViewerLivePill } from "./log-viewer.live-control";
import { LogViewerToolbar } from "./log-viewer.toolbar";
import type { LogWindow } from "./log-window";

function LogViewerRoot({
  className,
  children,
}: {
  className?: string;
  children?: ReactNode;
}) {
  return (
    <div
      className={cn(
        "flex h-full min-h-0 flex-1 flex-col gap-2 overflow-hidden p-1",
        className
      )}
      data-slot="log-viewer"
    >
      {children}
    </div>
  );
}

function LogViewerList({
  className,
  children,
}: {
  className?: string;
  children?: ReactNode;
}) {
  return (
    <div
      className={cn(
        "relative flex min-h-0 flex-1 flex-col overflow-hidden rounded-lg border border-border",
        className
      )}
      data-slot="log-viewer-list"
    >
      {children}
      <LogViewerLivePill />
    </div>
  );
}

function LogViewerVariant0({
  logs,
  className,
  logWindow,
  onLogWindowChange,
  searchQuery,
  onSearchQueryChange,
  truncatedAt,
}: {
  logs: LogsData;
  className?: string;
  logWindow?: LogWindow;
  onLogWindowChange?: (logWindow: LogWindow) => void;
  searchQuery?: string;
  onSearchQueryChange?: (q: string) => void;
  truncatedAt?: number;
}) {
  return (
    <LogViewerProvider
      externalLogWindow={logWindow}
      externalSearchQuery={searchQuery}
      logs={logs}
      onLogWindowChange={onLogWindowChange}
      onSearchQueryChange={onSearchQueryChange}
      truncatedAt={truncatedAt}
    >
      <LogViewerRoot className={className}>
        <LogViewerToolbar />
        <LogViewerCountChart />
        <LogViewerList>
          <LogViewerListHeader />
          <LogViewerListContent />
        </LogViewerList>
      </LogViewerRoot>
    </LogViewerProvider>
  );
}

export const LogViewer = {
  Provider: LogViewerProvider,
  Root: LogViewerRoot,
  Toolbar: LogViewerToolbar,
  CountChart: LogViewerCountChart,
  List: LogViewerList,
  ListHeader: LogViewerListHeader,
  ListContent: LogViewerListContent,
  Variant0: LogViewerVariant0,
};

import { format } from "date-fns";

/**
 * A log window is anchored either to "now" (live: relative span, follows new
 * output) or to fixed wall-clock bounds (frozen: never moves on its own).
 * There is no independent realtime flag — see docs/adr/0034.
 */
export type LogWindow =
  | { mode: "live"; spanMs: number }
  | { mode: "frozen"; start: Date; end: Date };

export interface LogWindowBounds {
  end: Date;
  start: Date;
}

export const LIVE_SPANS = [
  { label: "Last 5 min", ms: 5 * 60_000, short: "5m" },
  { label: "Last 15 min", ms: 15 * 60_000, short: "15m" },
  { label: "Last 30 min", ms: 30 * 60_000, short: "30m" },
  { label: "Last 1 hour", ms: 60 * 60_000, short: "1h" },
  { label: "Last 3 hours", ms: 3 * 60 * 60_000, short: "3h" },
  { label: "Last 6 hours", ms: 6 * 60 * 60_000, short: "6h" },
] as const;

export const DEFAULT_LIVE_SPAN_MS = 60 * 60_000;

export function logWindowBounds(
  logWindow: LogWindow,
  now = new Date()
): LogWindowBounds {
  if (logWindow.mode === "frozen") {
    return { end: logWindow.end, start: logWindow.start };
  }
  return {
    end: now,
    start: new Date(now.getTime() - logWindow.spanMs),
  };
}

/** Materialize a live window into fixed bounds; frozen windows pass through. */
export function freezeLogWindow(
  logWindow: LogWindow,
  now = new Date()
): LogWindow {
  if (logWindow.mode === "frozen") {
    return logWindow;
  }
  const { start, end } = logWindowBounds(logWindow, now);
  return { end, mode: "frozen", start };
}

export function liveSpanShortLabel(spanMs: number): string {
  const preset = LIVE_SPANS.find((span) => span.ms === spanMs);
  if (preset) {
    return preset.short;
  }
  const minutes = Math.round(spanMs / 60_000);
  if (minutes >= 60 && minutes % 60 === 0) {
    return `${minutes / 60}h`;
  }
  return `${minutes}m`;
}

/**
 * Frozen windows always read as their actual bounds, never as a relative
 * label: "Jul 2 · 11:15 – 12:15" same-day, "Jul 1 23:00 – Jul 2 01:00"
 * cross-day, with years added when a bound leaves the current year.
 */
export function formatFrozenWindowLabel(
  start: Date,
  end: Date,
  now = new Date()
): string {
  const withYear =
    start.getFullYear() !== now.getFullYear() ||
    end.getFullYear() !== now.getFullYear();
  const dayPattern = withYear ? "MMM d yyyy" : "MMM d";
  const sameDay =
    start.getFullYear() === end.getFullYear() &&
    start.getMonth() === end.getMonth() &&
    start.getDate() === end.getDate();
  if (sameDay) {
    return `${format(start, dayPattern)} · ${format(start, "HH:mm")} – ${format(end, "HH:mm")}`;
  }
  return `${format(start, `${dayPattern} HH:mm`)} – ${format(end, `${dayPattern} HH:mm`)}`;
}

export function formatLogWindowLabel(
  logWindow: LogWindow,
  now = new Date()
): string {
  if (logWindow.mode === "live") {
    return `Live · ${liveSpanShortLabel(logWindow.spanMs)}`;
  }
  return formatFrozenWindowLabel(logWindow.start, logWindow.end, now);
}

"use client";

import { Button } from "@workspace/ui/components/button";
import { Calendar } from "@workspace/ui/components/calendar";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@workspace/ui/components/popover";
import { TimeWheelField } from "@workspace/ui/components/time-wheel-field";
import { cn } from "@workspace/ui/lib/utils";
import { format } from "date-fns";
import { ChevronDown, Clock } from "lucide-react";
import { useEffect, useState } from "react";
import type { DateRange } from "react-day-picker";
import {
  formatLogWindowLabel,
  LIVE_SPANS,
  type LogWindow,
  logWindowBounds,
} from "./log-window";

interface LogWindowSelectorProps {
  className?: string;
  onChange: (logWindow: LogWindow) => void;
  value: LogWindow;
}

function draftBounds(
  range: DateRange | undefined,
  startTime: string,
  endTime: string
): { end: Date; start: Date } | null {
  if (!(range?.from && range?.to)) {
    return null;
  }
  const startParts = startTime.split(":").map(Number);
  const endParts = endTime.split(":").map(Number);
  const start = new Date(range.from);
  start.setHours(startParts[0] ?? 0, startParts[1] ?? 0, startParts[2] ?? 0, 0);
  const end = new Date(range.to);
  end.setHours(endParts[0] ?? 23, endParts[1] ?? 59, endParts[2] ?? 59, 999);
  if (start.getTime() >= end.getTime()) {
    return null;
  }
  return { end, start };
}

export function LogWindowSelector({
  value,
  onChange,
  className,
}: LogWindowSelectorProps) {
  const [open, setOpen] = useState(false);
  const [activeField, setActiveField] = useState<"start" | "end" | null>(null);
  const [draftRange, setDraftRange] = useState<DateRange | undefined>();
  const [draftStartTime, setDraftStartTime] = useState("00:00:00");
  const [draftEndTime, setDraftEndTime] = useState("23:59:59");

  useEffect(() => {
    if (!open) {
      return;
    }
    setActiveField(null);
    // Seed the frozen-window editor from the materialized bounds of whatever
    // is currently displayed — the "narrow down what I'm seeing" starting point.
    const { start, end } = logWindowBounds(value);
    setDraftRange({ from: start, to: end });
    setDraftStartTime(format(start, "HH:mm:ss"));
    setDraftEndTime(format(end, "HH:mm:ss"));
  }, [open, value]);

  const draft = draftBounds(draftRange, draftStartTime, draftEndTime);

  function handleApply() {
    if (!draft) {
      return;
    }
    onChange({ end: draft.end, mode: "frozen", start: draft.start });
    setOpen(false);
  }

  function handleLiveSpan(spanMs: number) {
    onChange({ mode: "live", spanMs });
    setOpen(false);
  }

  return (
    <Popover onOpenChange={setOpen} open={open}>
      <PopoverTrigger
        className={cn(
          "flex h-9 min-w-0 cursor-pointer items-center gap-2 rounded-md border border-input bg-transparent px-2.5 py-1 text-foreground text-sm outline-none transition-[color,box-shadow] hover:bg-input/30 focus-visible:border-blue-400 focus-visible:ring-[1px] focus-visible:ring-blue-400/50 aria-expanded:border-blue-400 aria-expanded:ring-[1px] aria-expanded:ring-blue-400/50 aria-expanded:ring-offset-0 dark:bg-transparent",
          className
        )}
      >
        {value.mode === "live" ? (
          <span
            aria-hidden
            className="size-2 shrink-0 rounded-full bg-blue-400"
          />
        ) : (
          <Clock className="size-4 shrink-0 text-muted-foreground" />
        )}
        <span className="truncate">{formatLogWindowLabel(value)}</span>
        <ChevronDown className="size-3.5 shrink-0 opacity-50" />
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-auto border border-border bg-input/30 p-0 text-foreground shadow-md ring-0 backdrop-blur-xl"
      >
        <div className="flex">
          <div className="flex flex-col gap-3 border-border border-r p-3">
            <Calendar
              classNames={{
                button_next:
                  "border border-input bg-transparent text-muted-foreground opacity-50 hover:bg-input/30 hover:text-foreground",
                button_previous:
                  "border border-input bg-transparent text-muted-foreground opacity-50 hover:bg-input/30 hover:text-foreground",
                day_button:
                  "data-[range-end=true]:bg-blue-500 data-[range-middle=true]:bg-input data-[range-start=true]:bg-blue-500 data-[selected-single=true]:bg-blue-500 data-[range-end=true]:text-foreground data-[range-middle=true]:text-foreground data-[range-start=true]:text-foreground data-[selected-single=true]:text-foreground hover:bg-input/30 dark:hover:bg-input/30",
                outside:
                  "text-muted-foreground opacity-50 aria-selected:text-muted-foreground",
                range_end:
                  "relative isolate -z-0 rounded-r-(--cell-radius) bg-input after:absolute after:inset-y-0 after:left-0 after:w-4 after:bg-input",
                range_middle: "rounded-none bg-input",
                range_start:
                  "relative isolate -z-0 rounded-l-(--cell-radius) bg-input after:absolute after:inset-y-0 after:right-0 after:w-4 after:bg-input",
                today:
                  "rounded-(--cell-radius) bg-input/30 text-foreground data-[selected=true]:rounded-none",
                weekday:
                  "flex-1 select-none rounded-(--cell-radius) font-normal text-[0.8rem] text-muted-foreground",
              }}
              mode="range"
              numberOfMonths={1}
              onSelect={setDraftRange}
              selected={draftRange}
            />
            <div className="flex gap-4 px-1">
              <TimeWheelField
                className="flex-1"
                label="Start"
                onChange={setDraftStartTime}
                onOpenChange={(next) => setActiveField(next ? "start" : null)}
                open={activeField === "start"}
                value={draftStartTime}
              />
              <TimeWheelField
                className="flex-1"
                label="End"
                onChange={setDraftEndTime}
                onOpenChange={(next) => setActiveField(next ? "end" : null)}
                open={activeField === "end"}
                value={draftEndTime}
              />
            </div>
            <div className="flex justify-end gap-2 px-1">
              <Button
                onClick={() => setOpen(false)}
                size="sm"
                variant="outline"
              >
                Cancel
              </Button>
              <Button
                className="bg-blue-500 text-foreground hover:bg-blue-500/90"
                disabled={!draft}
                onClick={handleApply}
                size="sm"
              >
                Apply
              </Button>
            </div>
          </div>
          <div className="flex flex-col gap-1 p-3">
            <span className="mb-1 flex items-center gap-1.5 font-medium text-muted-foreground text-xs">
              <span aria-hidden className="size-1.5 rounded-full bg-blue-400" />
              Live
            </span>
            {LIVE_SPANS.map((span) => (
              <button
                className={cn(
                  "rounded-md px-3 py-1.5 text-left text-foreground text-sm hover:bg-input/30",
                  value.mode === "live" &&
                    value.spanMs === span.ms &&
                    "bg-input font-medium"
                )}
                key={span.ms}
                onClick={() => handleLiveSpan(span.ms)}
                type="button"
              >
                {span.label}
              </button>
            ))}
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@workspace/ui/components/tooltip";
import { cn } from "@workspace/ui/lib/utils";
import { Pause, Play } from "lucide-react";
import { useLogViewerContext } from "./log-viewer.context";

/**
 * The window's anchor control: pause freezes a live window in place;
 * from a frozen window, the only way back to live is this explicit action
 * (or the in-list live pill).
 */
export function LogViewerLiveControl() {
  const { logWindow, freeze, resumeLive } = useLogViewerContext();
  const isLive = logWindow.mode === "live";

  return (
    <Tooltip>
      <TooltipTrigger
        aria-label={isLive ? "Pause live logs" : "Start live logs"}
        aria-pressed={isLive}
        className={cn(
          "flex size-9 shrink-0 cursor-pointer items-center justify-center rounded-lg border border-transparent shadow-none transition-colors focus-visible:border-ring focus-visible:ring-2 focus-visible:ring-ring/30",
          isLive
            ? "bg-input text-blue-400 hover:bg-input/80"
            : "bg-input/30 text-brand-primary-foreground hover:bg-input"
        )}
        onClick={isLive ? freeze : resumeLive}
        type="button"
      >
        {isLive ? <Pause className="size-4" /> : <Play className="size-4" />}
      </TooltipTrigger>
      <TooltipContent side="bottom">
        {isLive ? "Pause live logs" : "Start live logs"}
      </TooltipContent>
    </Tooltip>
  );
}

/**
 * Persistent exit from any frozen window, floating at the tail — the place
 * live output would appear. Hidden while live.
 */
export function LogViewerLivePill() {
  const { logWindow, resumeLive } = useLogViewerContext();

  if (logWindow.mode === "live") {
    return null;
  }

  return (
    <button
      className="absolute bottom-3 left-1/2 z-10 flex h-7 -translate-x-1/2 cursor-pointer items-center gap-1.5 rounded-full border border-border bg-background/80 px-3 font-medium text-foreground text-xs shadow-sm backdrop-blur transition-colors hover:bg-input/50"
      onClick={resumeLive}
      type="button"
    >
      <span aria-hidden className="size-1.5 rounded-full bg-blue-400" />
      Live
    </button>
  );
}

"use client";

import "@ncdai/react-wheel-picker/style.css";

import {
  WheelPicker,
  type WheelPickerOption,
  WheelPickerWrapper,
} from "@ncdai/react-wheel-picker";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@workspace/ui/components/popover";
import { cn } from "@workspace/ui/lib/utils";
import { Clock } from "lucide-react";
import { useEffect, useMemo, useRef } from "react";

function buildOptions(count: number): WheelPickerOption<number>[] {
  return Array.from({ length: count }, (_, index) => ({
    label: index.toString().padStart(2, "0"),
    value: index,
  }));
}

const HOUR_OPTIONS = buildOptions(24);
const MINUTE_OPTIONS = buildOptions(60);
const SECOND_OPTIONS = buildOptions(60);

function clampPart(value: number, max: number) {
  if (Number.isNaN(value)) {
    return 0;
  }
  return Math.min(Math.max(value, 0), max);
}

function parseTime(value: string): [number, number, number] {
  const [rawHours, rawMinutes, rawSeconds] = value.split(":");
  return [
    clampPart(Number.parseInt(rawHours ?? "0", 10), 23),
    clampPart(Number.parseInt(rawMinutes ?? "0", 10), 59),
    clampPart(Number.parseInt(rawSeconds ?? "0", 10), 59),
  ];
}

function formatTime(hours: number, minutes: number, seconds: number) {
  return [hours, minutes, seconds]
    .map((part) => part.toString().padStart(2, "0"))
    .join(":");
}

const SHARED_WHEEL_CLASS_NAMES = {
  highlightItem: "font-normal text-foreground text-sm",
  optionItem: "font-normal text-foreground text-sm",
};

// The library ships an *unlayered* CSS mask that only fades the outer ~20% of
// each column, and unlayered CSS beats Tailwind's layered utilities — so a
// utility override silently loses. We apply a stronger mask via inline styles
// (which always win) once the portalled columns have mounted.
const WHEEL_EDGE_MASK =
  "linear-gradient(to bottom, transparent 0%, black 26%, black 74%, transparent 100%)";

interface TimeWheelFieldProps {
  className?: string;
  label: string;
  onChange: (value: string) => void;
  onOpenChange: (open: boolean) => void;
  open: boolean;
  value: string;
}

/**
 * Read-only time field that reveals an iOS-style hour/minute/second wheel
 * picker beneath itself. The wheel lives in a portalled popover so its frosted
 * `backdrop-blur` is not suppressed by the parent popover's own backdrop
 * filter. `open` is controlled by the parent so only one field (Start or End)
 * can be expanded at a time.
 */
export function TimeWheelField({
  className,
  label,
  onChange,
  onOpenChange,
  open,
  value,
}: TimeWheelFieldProps) {
  const wheelsRef = useRef<HTMLDivElement>(null);
  const [hours, minutes, seconds] = useMemo(() => parseTime(value), [value]);

  // Replace the library's built-in edge mask with a stronger fade that dims the
  // neighbouring rows, not just the outermost sliver. Inline styles beat the
  // library's unlayered CSS rule; retry across frames until the portalled
  // columns mount.
  useEffect(() => {
    if (!open) {
      return;
    }
    let frame = 0;
    let tries = 0;
    const applyMask = () => {
      const columns =
        wheelsRef.current?.querySelectorAll<HTMLElement>("[data-rwp]");
      if ((!columns || columns.length === 0) && tries < 30) {
        tries += 1;
        frame = requestAnimationFrame(applyMask);
        return;
      }
      for (const column of columns ?? []) {
        column.style.setProperty("mask-image", WHEEL_EDGE_MASK);
        column.style.setProperty("-webkit-mask-image", WHEEL_EDGE_MASK);
      }
    };
    applyMask();
    return () => cancelAnimationFrame(frame);
  }, [open]);

  return (
    <div className={cn("flex flex-col gap-2", className)}>
      <span className="text-foreground text-sm">{label}</span>
      <Popover onOpenChange={onOpenChange} open={open}>
        <PopoverTrigger
          render={
            <button
              className={cn(
                "flex h-9 items-center justify-between gap-2 rounded-md border border-input bg-transparent py-1 pr-3 pl-4 text-foreground text-sm outline-none transition-[color,box-shadow] hover:bg-input/30",
                open && "border-blue-400 ring-[1px] ring-blue-400/50"
              )}
              type="button"
            />
          }
        >
          <span className="tabular-nums">
            {formatTime(hours, minutes, seconds)}
          </span>
          <Clock className="size-4 shrink-0 text-muted-foreground" />
        </PopoverTrigger>
        <PopoverContent
          align="start"
          className="w-[150px] overflow-hidden rounded-lg border border-border bg-input/30 p-1 ring-0 backdrop-blur-xl"
          sideOffset={4}
        >
          <div ref={wheelsRef}>
            <WheelPickerWrapper>
              <WheelPicker
                classNames={{
                  ...SHARED_WHEEL_CLASS_NAMES,
                  highlightWrapper: "rounded-l-md bg-blue-500",
                }}
                infinite
                onValueChange={(next) =>
                  onChange(formatTime(next, minutes, seconds))
                }
                optionItemHeight={36}
                options={HOUR_OPTIONS}
                value={hours}
                visibleCount={12}
              />
              <WheelPicker
                classNames={{
                  ...SHARED_WHEEL_CLASS_NAMES,
                  highlightWrapper: "bg-blue-500",
                }}
                infinite
                onValueChange={(next) =>
                  onChange(formatTime(hours, next, seconds))
                }
                optionItemHeight={36}
                options={MINUTE_OPTIONS}
                value={minutes}
                visibleCount={12}
              />
              <WheelPicker
                classNames={{
                  ...SHARED_WHEEL_CLASS_NAMES,
                  highlightWrapper: "rounded-r-md bg-blue-500",
                }}
                infinite
                onValueChange={(next) =>
                  onChange(formatTime(hours, minutes, next))
                }
                optionItemHeight={36}
                options={SECOND_OPTIONS}
                value={seconds}
                visibleCount={12}
              />
            </WheelPickerWrapper>
          </div>
        </PopoverContent>
      </Popover>
    </div>
  );
}

"use client";

import {
  createContext,
  use,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import {
  DEFAULT_LIVE_SPAN_MS,
  freezeLogWindow,
  type LogWindow,
} from "./log-window";

export interface LogEntry {
  container: string;
  message: string;
  node: string;
  pod: string;
  stream: string;
  time: string;
}

export type LogsData = LogEntry[];

interface LogViewerContextValue {
  entries: LogEntry[];
  filteredEntries: LogEntry[];
  /** Freeze the current window in place, materializing live bounds. */
  freeze: () => void;
  logWindow: LogWindow;
  /** Re-anchor to now using the last live span. Always explicit. */
  resumeLive: () => void;
  searchQuery: string;
  selectedContainers: string[];
  selectedPods: string[];
  setLogWindow: (logWindow: LogWindow) => void;
  setSearchQuery: (q: string) => void;
  setSelectedContainers: (containers: string[]) => void;
  setSelectedPods: (pods: string[]) => void;
  /** When set, the fetch was truncated to the newest N lines of the window. */
  truncatedAt?: number;
  uniqueContainers: string[];
  uniquePods: string[];
}

const LogViewerContext = createContext<LogViewerContextValue | null>(null);

export function useLogViewerContext() {
  const ctx = use(LogViewerContext);
  if (!ctx) {
    throw new Error(
      "LogViewer compound components must be used within LogViewer.Provider"
    );
  }
  return ctx;
}

export function LogViewerProvider({
  logs,
  children,
  externalLogWindow,
  onLogWindowChange,
  externalSearchQuery,
  onSearchQueryChange,
  truncatedAt,
}: {
  logs: LogsData;
  children: React.ReactNode;
  externalLogWindow?: LogWindow;
  onLogWindowChange?: (logWindow: LogWindow) => void;
  externalSearchQuery?: string;
  onSearchQueryChange?: (q: string) => void;
  truncatedAt?: number;
}) {
  const [selectedPods, setSelectedPods] = useState<string[]>([]);
  const [selectedContainers, setSelectedContainers] = useState<string[]>([]);
  const [internalSearchQuery, setInternalSearchQuery] = useState("");
  const [internalLogWindow, setInternalLogWindow] = useState<LogWindow>({
    mode: "live",
    spanMs: DEFAULT_LIVE_SPAN_MS,
  });

  // Controlled-or-uncontrolled pattern
  const searchQuery =
    externalSearchQuery === undefined
      ? internalSearchQuery
      : externalSearchQuery;
  const setSearchQuery = onSearchQueryChange ?? setInternalSearchQuery;
  const logWindow = externalLogWindow ?? internalLogWindow;
  const setLogWindow = onLogWindowChange ?? setInternalLogWindow;

  const lastLiveSpanRef = useRef(DEFAULT_LIVE_SPAN_MS);
  useEffect(() => {
    if (logWindow.mode === "live") {
      lastLiveSpanRef.current = logWindow.spanMs;
    }
  }, [logWindow]);

  const freeze = useCallback(() => {
    if (logWindow.mode === "live") {
      setLogWindow(freezeLogWindow(logWindow));
    }
  }, [logWindow, setLogWindow]);

  const resumeLive = useCallback(() => {
    setLogWindow({ mode: "live", spanMs: lastLiveSpanRef.current });
  }, [setLogWindow]);

  // Windowing is the data layer's job; entries are trusted to match the
  // window. Sorting here guarantees the oldest-to-newest invariant the list,
  // chart, and live tail rely on.
  const entries = useMemo(
    () => [...logs].sort((a, b) => a.time.localeCompare(b.time)),
    [logs]
  );

  const uniquePods = useMemo(
    () => [...new Set(entries.map((e) => e.pod))].sort(),
    [entries]
  );

  const uniqueContainers = useMemo(
    () => [...new Set(entries.map((e) => e.container))].sort(),
    [entries]
  );

  const filteredEntries = useMemo(() => {
    let result = entries;
    if (selectedPods.length > 0) {
      result = result.filter((e) => selectedPods.includes(e.pod));
    }
    if (selectedContainers.length > 0) {
      result = result.filter((e) => selectedContainers.includes(e.container));
    }
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      result = result.filter((e) => e.message.toLowerCase().includes(q));
    }
    return result;
  }, [entries, selectedPods, selectedContainers, searchQuery]);

  const value: LogViewerContextValue = useMemo(
    () => ({
      entries,
      filteredEntries,
      freeze,
      logWindow,
      resumeLive,
      searchQuery,
      selectedContainers,
      selectedPods,
      setLogWindow,
      setSearchQuery,
      setSelectedContainers,
      setSelectedPods,
      truncatedAt,
      uniqueContainers,
      uniquePods,
    }),
    [
      entries,
      filteredEntries,
      freeze,
      logWindow,
      resumeLive,
      searchQuery,
      selectedContainers,
      selectedPods,
      setLogWindow,
      setSearchQuery,
      truncatedAt,
      uniqueContainers,
      uniquePods,
    ]
  );

  return (
    <LogViewerContext.Provider value={value}>
      {children}
    </LogViewerContext.Provider>
  );
}

